F=np.load('feats.npz'); y=F['y']; folds=np.load('folds.npy'); A=dict(np.load('featsA.npz'))
def stdz(X,tr): mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; return (X-mu)/sd
def cv(featfn, lam, folds=folds):
    accs=[]
    for f in range(5):
        tr=folds!=f; te=~tr
        Z=featfn(tr); mu=Z[tr].mean(0); Zc=Z-mu
        Y=np.eye(8)[y[tr]]-1/8
        K=Zc@Zc[tr].T; a=np.linalg.solve(K[tr]+lam*np.eye(tr.sum()),Y); pr=K[te]@a
        accs.append((np.argmax(pr,1)==y[te]).mean())
    return round(np.mean(accs),4)
for R in [9,10]:
    for wc in [0.7,1.0]:
        fn=lambda tr: np.concatenate([wc*stdz(A[f'C{R}'],tr),stdz(A[f'M{R}'],tr)],1)
        print("tapped [C%d',M%d'] wc"%(R,R),wc,[cv(fn,l) for l in [100,200,300,500,800]])
        fn=lambda tr: np.concatenate([wc*stdz(F[f'C{R}'],tr),stdz(F[f'M{R}'],tr)],1)
        print("base   [C%d,M%d] wc"%(R,R),wc,[cv(fn,l) for l in [100,200,300,500,800]])
